package com.yeyamo_mobile.api.catalog_service.application;
import com.yeyamo_mobile.api.catalog_service.application.port.OutboxPort;import com.yeyamo_mobile.api.catalog_service.infrastructure.persistence.*;import com.yeyamo_mobile.api.catalog_service.interfaces.rest.ArtworkDtos;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.security.oauth2.jwt.Jwt;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ArtworkServiceTest{
 @Mock ArtworkRepositories.Artworks artworks;@Mock SpringDataCatalogAssetRepository assets;@Mock ArtworkRepositories.Translations translations;@Mock ArtworkRepositories.Histories histories;@Mock ArtworkRepositories.Media media;@Mock OutboxPort outbox;ArtworkService service;AutoCloseable mocks;
 @BeforeEach void setup(){mocks=MockitoAnnotations.openMocks(this);service=new ArtworkService(artworks,assets,translations,histories,media,outbox);}@AfterEach void close()throws Exception{mocks.close();}
 @Test void rejectsAnotherPartner(){UUID owner=UUID.randomUUID();ArtworkEntity a=new ArtworkEntity();a.assetId=UUID.randomUUID();a.artisanPartnerId=owner;when(artworks.locked(a.assetId)).thenReturn(Optional.of(a));Jwt jwt=Jwt.withTokenValue("x").header("alg","none").subject("user").claim("partnerId",UUID.randomUUID().toString()).issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(60)).build();assertThrows(SecurityException.class,()->service.delete(a.assetId,jwt,"c"));}
 @Test void softDeleteKeepsRecord(){UUID owner=UUID.randomUUID();ArtworkEntity a=new ArtworkEntity();a.assetId=UUID.randomUUID();a.artisanPartnerId=owner;a.availabilityStatus=ArtworkEntity.AvailabilityStatus.AVAILABLE;a.countryCode="CM";when(artworks.locked(a.assetId)).thenReturn(Optional.of(a));when(artworks.save(any())).thenAnswer(i->i.getArgument(0));Jwt jwt=Jwt.withTokenValue("x").header("alg","none").subject("user").claim("partnerId",owner.toString()).issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(60)).build();service.delete(a.assetId,jwt,"c");assertNotNull(a.deletedAt);assertEquals(ArtworkEntity.AvailabilityStatus.UNAVAILABLE,a.availabilityStatus);verify(artworks).save(a);}
}
